-- Etapa 37: 18 questões originais de Matemática; geradas com auxílio de IA.
-- Revisão humana pendente. Gerado por scripts/build-math-content.mjs.
-- Apenas INSERT atômico em draft; reexecução preserva conteúdo, status e gabaritos.
-- Não reparar um gabarito de questão existente silenciosamente.
with source_data (id, statement, option_a, option_b, option_c, option_d, option_e,
                  topic, difficulty, correct_answer, explanation) as (
  values
  ('d1370000-0000-4000-8000-000000000001', 'Uma garrafa continha 3/4 de litro de água. Depois de beber 1/3 de litro, quantos litros de água restaram na garrafa?', '1/4 de litro', '1/2 de litro', '5/12 de litro', '2/3 de litro', '7/12 de litro', 'Frações', 'easy', 'C', 'Usando o denominador comum 12: 3/4 − 1/3 = 9/12 − 4/12 = 5/12 de litro.'),
  ('d1370000-0000-4000-8000-000000000002', 'Às 6 horas, a temperatura era de −3 °C. Até o meio-dia, ela aumentou 8 °C e, depois, diminuiu 4 °C. Qual foi a temperatura após essa diminuição?', '−15 °C', '−1 °C', '5 °C', '9 °C', '1 °C', 'Números inteiros', 'easy', 'E', 'A temperatura passou de −3 °C para −3 + 8 = 5 °C. Após cair 4 °C, ficou em 5 − 4 = 1 °C.'),
  ('d1370000-0000-4000-8000-000000000003', 'Qual é o valor da expressão 2³ + 3 × (5 − 1)?', '20', '44', '32', '14', '24', 'Potências e operações', 'medium', 'A', 'Primeiro, 2³ = 8 e 5 − 1 = 4. Em seguida, 3 × 4 = 12. Por fim, 8 + 12 = 20.'),
  ('d1370000-0000-4000-8000-000000000004', 'Uma papelaria vende três canetas de mesmo preço e um caderno de R$ 7,00 por um total de R$ 22,00. Qual é o preço de cada caneta?', 'R$ 3,00', 'R$ 7,00', 'R$ 15,00', 'R$ 5,00', 'R$ 9,00', 'Equação do primeiro grau', 'easy', 'D', 'Se x é o preço de cada caneta, 3x + 7 = 22. Assim, 3x = 15 e x = 5. Cada caneta custa R$ 5,00.'),
  ('d1370000-0000-4000-8000-000000000005', 'Em uma sessão de cinema, o ingresso inteiro custa R$ 20,00 e a meia-entrada custa R$ 10,00. Foram vendidos 12 ingressos, totalizando R$ 190,00. Quantos ingressos inteiros foram vendidos?', '5', '7', '8', '9', '10', 'Sistema de equações', 'medium', 'B', 'Se i é a quantidade de ingressos inteiros, há 12 − i meias-entradas. Logo, 20i + 10(12 − i) = 190, ou 10i = 70. Portanto, i = 7.'),
  ('d1370000-0000-4000-8000-000000000006', 'Um produto custa R$ 200,00. Seu preço aumenta 10% e, em seguida, recebe um desconto de 10% sobre o preço já aumentado. Qual é o preço final?', 'R$ 180,00', 'R$ 200,00', 'R$ 198,00', 'R$ 202,00', 'R$ 220,00', 'Variações percentuais sucessivas', 'medium', 'C', 'Após o aumento, o preço é 200 × 1,10 = R$ 220,00. O desconto seguinte é de 10% de 220, isto é, R$ 22,00. O preço final é R$ 198,00. As duas porcentagens usam bases diferentes.'),
  ('d1370000-0000-4000-8000-000000000007', 'Um prêmio de R$ 450,00 será dividido entre Ana e Bruno na razão 2:3, respectivamente. Quanto Bruno receberá?', 'R$ 150,00', 'R$ 180,00', 'R$ 225,00', 'R$ 300,00', 'R$ 270,00', 'Divisão proporcional', 'medium', 'E', 'A divisão tem 2 + 3 = 5 partes iguais. Cada parte vale 450 ÷ 5 = R$ 90,00. Bruno recebe três partes: 3 × 90 = R$ 270,00.'),
  ('d1370000-0000-4000-8000-000000000008', 'Quatro máquinas iguais, trabalhando no mesmo ritmo, produzem um lote em 6 horas. Sem interrupções, quanto tempo seis dessas máquinas levam para produzir o mesmo lote?', '4 horas', '9 horas', '3 horas', '6 horas', '8 horas', 'Proporcionalidade inversa', 'medium', 'A', 'O trabalho exige 4 × 6 = 24 máquina-horas. Com seis máquinas iguais, o tempo é 24 ÷ 6 = 4 horas.'),
  ('d1370000-0000-4000-8000-000000000009', 'Um jardim retangular mede 8 m de comprimento e 5 m de largura. Qual é o comprimento de uma cerca que contorna todo o jardim, sem abertura para portão?', '13 m', '40 m', '20 m', '26 m', '80 m', 'Perímetro do retângulo', 'easy', 'D', 'O perímetro soma os quatro lados: 8 + 5 + 8 + 5 = 26 m, ou 2 × (8 + 5). A área de 40 m² não mede o comprimento da cerca.'),
  ('d1370000-0000-4000-8000-000000000010', 'Uma placa triangular tem base de 12 cm e altura perpendicular a essa base de 7 cm. Qual é a área da placa?', '84 cm²', '42 cm²', '19 cm²', '38 cm²', '21 cm²', 'Área do triângulo', 'easy', 'B', 'A área de um triângulo é base × altura ÷ 2. Assim, 12 × 7 ÷ 2 = 42 cm².'),
  ('d1370000-0000-4000-8000-000000000011', 'Uma pista tem formato de circunferência com raio de 10 m. Usando π = 3,14 e C = 2πr, qual é a distância de uma volta completa?', '31,4 m', '314 m', '62,8 m', '20 m', '628 m', 'Comprimento da circunferência', 'medium', 'C', 'Substituindo o raio na fórmula fornecida: C = 2 × 3,14 × 10 = 62,8 m. O diâmetro é 20 m, mas não representa uma volta completa.'),
  ('d1370000-0000-4000-8000-000000000012', 'Uma caixa retangular tem dimensões internas de 40 cm, 25 cm e 20 cm. Sabendo que 1 litro corresponde a 1.000 cm³, qual é a capacidade total da caixa?', '2 litros', '10 litros', '85 litros', '200 litros', '20 litros', 'Volume e capacidade', 'medium', 'E', 'O volume interno é 40 × 25 × 20 = 20.000 cm³. Dividindo por 1.000, obtemos a capacidade de 20 litros.'),
  ('d1370000-0000-4000-8000-000000000013', 'Uma escada reta de 5 m está apoiada em uma parede vertical, sobre um chão horizontal. A base da escada fica a 3 m da parede. A que altura do chão está a extremidade superior da escada?', '4 m', '2 m', '8 m', '√34 m', '3 m', 'Teorema de Pitágoras', 'medium', 'A', 'Parede e chão formam um ângulo reto. A escada é a hipotenusa: h² + 3² = 5². Logo, h² = 25 − 9 = 16 e a altura positiva é h = 4 m.'),
  ('d1370000-0000-4000-8000-000000000014', 'As notas de uma estudante em quatro atividades com o mesmo peso foram 6, 7, 8 e 9. Qual nota ela precisa obter na quinta atividade, também com o mesmo peso, para ficar com média 8 nas cinco atividades?', '8', '9', '7', '10', '6', 'Média aritmética', 'medium', 'D', 'Para média 8 em cinco atividades, a soma deve ser 5 × 8 = 40. As quatro notas somam 30. Portanto, a quinta nota deve ser 40 − 30 = 10.'),
  ('d1370000-0000-4000-8000-000000000015', 'Cinco estudantes levaram 18, 12, 20, 15 e 15 minutos para concluir uma tarefa. Qual é a mediana desses tempos?', '16 minutos', '15 minutos', '18 minutos', '12 minutos', '20 minutos', 'Mediana', 'medium', 'B', 'Ordenando os tempos, temos 12, 15, 15, 18 e 20. Como há cinco valores, a mediana é o terceiro valor: 15 minutos.'),
  ('d1370000-0000-4000-8000-000000000016', 'Em uma caixa há 3 bolas vermelhas, 2 azuis e 5 verdes, de mesmo tamanho e indistinguíveis pelo toque. Ao retirar uma única bola ao acaso, qual é a probabilidade de ela ser azul?', '1/2', '2/5', '1/5', '3/10', '4/5', 'Probabilidade', 'medium', 'C', 'Há 3 + 2 + 5 = 10 bolas, das quais duas são azuis. A probabilidade é 2/10 = 1/5. A retirada ao acaso dá a cada bola a mesma chance.'),
  ('d1370000-0000-4000-8000-000000000017', 'O preço de uma corrida é calculado por uma taxa fixa de R$ 6,00 mais R$ 2,50 por quilômetro percorrido, sem outros acréscimos. Quanto custa uma corrida de 8 km?', 'R$ 20,00', 'R$ 14,00', 'R$ 22,00', 'R$ 28,00', 'R$ 26,00', 'Função afim', 'medium', 'E', 'A função do preço é P(x) = 6 + 2,50x. Para 8 km: P(8) = 6 + 2,50 × 8 = 6 + 20 = R$ 26,00.'),
  ('d1370000-0000-4000-8000-000000000018', 'Uma ciclista percorreu 18 km em 45 minutos. Qual foi sua velocidade média, em quilômetros por hora, nesse percurso?', '18 km/h', '24 km/h', '13,5 km/h', '40 km/h', '30 km/h', 'Velocidade média', 'medium', 'B', '45 minutos equivalem a 45/60 = 0,75 hora. A velocidade média é distância ÷ tempo: 18 ÷ 0,75 = 24 km/h.')
), inserted_questions as (
  insert into public.questions (id, statement, option_a, option_b, option_c, option_d, option_e,
                               subject, topic, difficulty, target_exam, status, version)
  select id::uuid, statement, option_a, option_b, option_c, option_d, option_e,
         'matematica', topic, difficulty, 'both', 'draft', 1 from source_data
  on conflict (id) do nothing
  returning id
)
insert into public.question_answers (question_id, correct_answer, explanation)
select q.id, s.correct_answer, s.explanation
from inserted_questions q join source_data s on s.id::uuid = q.id;
